//--------------------------------------------------------------
//File name:   dash_font_data.h
//Layout of the pre-rasterized dashboard font (src/dash_font_data.c,
//generated by scripts/gen_dash_font.py).
//--------------------------------------------------------------
#ifndef DASH_FONT_DATA_H
#define DASH_FONT_DATA_H

#include <tamtypes.h>

#define DASH_FONT_FIRST 0x20
#define DASH_FONT_LAST 0xFF
#define DASH_FONT_GLYPHS (DASH_FONT_LAST - DASH_FONT_FIRST + 1)
#define DASH_FONT_FACES 3

typedef struct
{
	u16 x, y;   /* atlas position */
	u8 w, h;    /* bitmap size (0 = no ink, e.g. space) */
	s8 xoff;    /* bitmap left relative to the pen */
	s8 yoff;    /* bitmap top relative to the line top (ascender) */
	u16 adv16;  /* advance in 1/16 px */
} DashGlyphData;

typedef struct
{
	int em;                        /* pixel size the face was rendered at */
	int alpha_gamma100;            /* atlas alpha exponent, multiplied by 100 */
	int ascent16, descent16;       /* 1/16 px */
	int xheight16;                 /* 1/16 px */
	int tex_w, tex_h;
	const u8 *pixels;              /* PSMT8 alpha, tex_w * tex_h */
	const DashGlyphData *glyphs;   /* indexed by code - DASH_FONT_FIRST */
} DashFaceData;

/* Three sizes per family; only the selected family's textures are resident. */
extern const DashFaceData dash_font_faces[DASH_FONT_FACES];
extern const DashFaceData dash_emotion_engine_faces[DASH_FONT_FACES];
extern const DashFaceData dash_emotion_engine_bold_faces[DASH_FONT_FACES];

#endif
